164      public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod) {
165          Option<Expr> optBody = NodeUtil.getBody(defn);
166          if (optBody.isNone()) return defn;
167          Expr body = optBody.unwrap();
168          Expr fn;
169          Expr arg;
170          if (body instanceof Juxt && ((Juxt) body).isTight()) {
171              List<Expr> juxts = ((Juxt) body).getExprs();
172              if (juxts.size() != 2) return defn;
173              fn = juxts.get(0);
174              arg = juxts.get(1);
175          } else if (body instanceof MathPrimary) {
176              MathPrimary mp = (MathPrimary) body;
177              List<MathItem> args = mp.getRest();
178              if (args.size() != 1) return defn;
179              fn = mp.getFront();
180              MathItem mi = args.get(0);
181              if (mi instanceof ExprMI) arg = ((ExprMI) mi).getExpr();
182              else return defn;
183          } else // (!(body instanceof TightJuxt || body instanceof MathPrimary))
184              return defn;
185          if (!(fn instanceof VarRef)) return defn;
186          if (!(arg instanceof StringLiteralExpr)) return defn;
187          Id name = ((VarRef) fn).getVarId();
188          if (!name.getText().equals("builtinPrimitive")) return defn;
189          String str = ((StringLiteralExpr) arg).getText();
190          Pair<String, Applicable> key = new Pair<String, Applicable>(str, defn);
191          synchronized (cache) {
192              NativeApp res = cache.get(key);
193              if (res != null) return res;
194              try {
195                  // System.err.println("Loading primitive class "+str);
196                  Class nativeAct = Class.forName(str);
197                  res = (NativeApp) nativeAct.newInstance();
198                  res.init(defn, isFunctionalMethod);
199                  cache.put(key, res);
200                  return res;
201              }
202              catch (java.lang.ClassNotFoundException x) {
